# Field-Level Equivalence Detector - runnable demo (JAH-ATK184S-000001)
import re
RANK = 1
SIG = True
FIELDS = [('zip', ['10001', '90210']), ('postal_code', ['10001', '30301']), ('zipcode', ['90210', '10001']), ('email', ['a@x.com'])]  # (field_name, [sample values])
def pattern(vals):
    s = " ".join(vals)
    if re.fullmatch(r"(\d{5} ?)+", s.replace(" ", " ").strip().replace("  ", " ")): return "zip?"
    if all(re.fullmatch(r"\d{5}", v) for v in vals): return "ZIP5"
    if all("@" in v for v in vals): return "EMAIL"
    return "TEXT"
def jaccard(a, b):
    a, b = set(a), set(b)
    return len(a & b)/len(a | b) if a | b else 0.0
groups, used = [], set()
for i, (n1, v1) in enumerate(FIELDS):
    if i in used: continue
    g = [n1]; used.add(i)
    for j, (n2, v2) in enumerate(FIELDS):
        if j in used: continue
        if jaccard(v1, v2) >= 0.5 or pattern(v1) == pattern(v2) != "TEXT":
            g.append(n2); used.add(j)
    groups.append(g)
for g in groups: print("equivalent group:", g)
if RANK >= 2: print("fields:", len(FIELDS), "| groups:", len(groups))
if RANK >= 3:
    for n, v in FIELDS: print("  %-12s pattern=%s" % (n, pattern(v)))
if SIG:
    print("Signature lineage stamp: JAH-SIG-EQV-" + "JAH-ATK184S-000001")
print("record:", "JAH-ATK184S-000001", "OK")

